package local.ondemand;
import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
final class TitlePages {
 static void detail(MainActivity a,JSONObject m,String type){a.selected=m;a.type=type;if(type.equals("movie")){a.videoId=m.optString("id");a.videoName=m.optString("name");a.sourceList();return;}final String id=m.optString("id");a.screen(m.optString("name"),"Loading seasons and episodes…");a.load(()->{JSONObject full=a.api.meta(type,id);return ()->render(a,m,full,type);});}
 static void render(MainActivity a,JSONObject m,JSONObject full,String type){a.selected=full;a.type=type;if(type.equals("movie")){a.videoId=full.optString("id");a.videoName=full.optString("name");a.sourceList();return;}SortedSet<Integer> seasons=EpisodeInfo.seasons(full);int season=a.seriesSeasons.containsKey(full.optString("id"))?a.seriesSeasons.get(full.optString("id")):-1;if(!seasons.contains(season)){season=seasons.isEmpty()?0:seasons.first();for(JSONObject recent:WatchLibrary.recent(a))if(recent.optString("id").equals(full.optString("id"))){String[] parts=recent.optString("lastEpisode").split(":");try{int last=Integer.parseInt(parts[1]);if(seasons.contains(last))season=last;}catch(Exception ignored){}}}series(a,full,season);}
 static void hero(MainActivity a,JSONObject m,int height){if(m.optString("poster").isEmpty()&&m.optString("description").isEmpty())return;LinearLayout hero=new LinearLayout(a);ImageView poster=new ImageView(a);poster.setScaleType(ImageView.ScaleType.FIT_CENTER);hero.addView(poster,new LinearLayout.LayoutParams(a.dp(height*2/3),a.dp(height)));a.poster(poster,m.optString("poster"),a.generation);TextView description=a.text(m.optString("description",""),12);description.setMaxLines(height>80?5:3);description.setEllipsize(android.text.TextUtils.TruncateAt.END);description.setPadding(a.dp(12),0,0,0);hero.addView(description,new LinearLayout.LayoutParams(0,a.dp(height),1));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,a.dp(height));p.bottomMargin=a.dp(7);a.rows.addView(hero,p);}
 static void series(MainActivity a,JSONObject full,int season){a.selected=full;a.type="series";a.seriesSeasons.put(full.optString("id"),season);a.rows.removeAllViews();a.status.setText("Choose a season, then an episode · Hold OK for watched options");hero(a,full,66);List<View> seasonButtons=new ArrayList<>(),cards=new ArrayList<>();HorizontalScrollView seasons=new HorizontalScrollView(a);seasons.setTag("seasons:carousel");seasons.setHorizontalScrollBarEnabled(false);seasons.setFocusable(false);seasons.setFillViewport(true);LinearLayout line=new LinearLayout(a);line.setTag("seasons:row");seasons.addView(line,new HorizontalScrollView.LayoutParams(-2,-2));a.rows.addView(seasons,new LinearLayout.LayoutParams(-1,-2));for(int s:EpisodeInfo.seasons(full)){Button b=a.button(EpisodeInfo.label(s),()->{series(a,full,s);View chosen=a.rows.findViewWithTag("season:"+s);if(chosen!=null)chosen.requestFocus();});b.setTextSize(12);b.setPadding(a.dp(5),0,a.dp(5),0);b.setTag("season:"+s);if(s==season)b.setBackground(a.shape(0xff29374d,0xffedf0ff,7));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams((a.getResources().getDisplayMetrics().widthPixels-a.dp(40))/6-a.dp(6),a.dp(32));p.setMargins(0,0,a.dp(6),a.dp(6));line.addView(b,p);seasonButtons.add(b);}
 List<JSONObject> episodes=EpisodeInfo.episodes(full,season);if(episodes.isEmpty())a.rows.addView(a.text("No confirmed episodes are listed yet.",13));HorizontalScrollView carousel=new HorizontalScrollView(a);carousel.setTag("episodes:carousel");carousel.setFillViewport(true);carousel.setClipToPadding(false);carousel.setPadding(a.dp(2),a.dp(3),a.dp(2),a.dp(5));carousel.setHorizontalScrollBarEnabled(false);carousel.setFocusable(false);line=new LinearLayout(a);line.setTag("episodes:row");carousel.addView(line,new HorizontalScrollView.LayoutParams(-2,-2));a.rows.addView(carousel,new LinearLayout.LayoutParams(-1,-2));int width=(a.getResources().getDisplayMetrics().widthPixels-a.dp(40)-a.dp(24))/4;for(int i=0;i<episodes.size();i++){JSONObject ep=episodes.get(i);String id=ep.optString("id");LinearLayout card=new LinearLayout(a);card.setOrientation(1);card.setTag("episode:"+id);card.setId(View.generateViewId());card.setFocusable(true);card.setClickable(true);card.setDescendantFocusability(android.view.ViewGroup.FOCUS_BLOCK_DESCENDANTS);card.setPadding(a.dp(3),a.dp(3),a.dp(3),a.dp(3));card.setBackground(a.shape(0xff1c1e28,0xff303644,7));card.setOnFocusChangeListener((v,f)->v.setBackground(a.shape(f?0xff29374d:0xff1c1e28,f?0xffedf0ff:0xff303644,7)));ImageView image=new ImageView(a);image.setTag("episode:screenshot:"+id);image.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(image,new LinearLayout.LayoutParams(-1,(width-a.dp(6))*9/16));a.poster(image,EpisodeInfo.image(ep,full),a.generation);TextView title=a.text((WatchLibrary.watched(a,id)?"✓ ":"")+"E"+ep.optInt("episode")+" · "+ep.optString("title",ep.optString("name","Episode")),12);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(title,new LinearLayout.LayoutParams(-1,a.dp(32)));TextView date=a.text(EpisodeInfo.upcoming(ep)?"Expected "+EpisodeInfo.date(ep):"Hold OK · watched options",10);date.setSingleLine();card.addView(date);card.setOnClickListener(v->{if(EpisodeInfo.upcoming(ep)){android.widget.Toast.makeText(a,"Not aired yet · Expected "+EpisodeInfo.date(ep),0).show();return;}a.go(()->episode(a,full,ep,season));});card.setOnLongClickListener(v->{watchedMenu(a,id,()->{a.restoreFocus="episode:"+id;series(a,full,season);});return true;});LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(width,-2);cp.setMargins(0,0,a.dp(8),a.dp(8));line.addView(card,cp);cards.add(card);}
 a.seriesRelated=new SeriesRelated(a,full,season,cards);
 for(int i=0;i<seasonButtons.size();i++){final int at=i;seasonButtons.get(i).setOnKeyListener((v,k,e)->{View next=k==20?(!cards.isEmpty()?cards.get(0):v):k==21?seasonButtons.get(Math.max(0,at-1)):k==22?seasonButtons.get(Math.min(seasonButtons.size()-1,at+1)):k==19?v:null;if(next==null)return false;if(e.getAction()==0)next.requestFocus();return true;});}
 for(int i=0;i<cards.size();i++){final int at=i;cards.get(i).setOnKeyListener((v,k,e)->{int index=k==21?Math.max(0,at-1):k==22?Math.min(at+1,cards.size()-1):k==20?at:k==19?-2:-1;if(index==-1)return false;if(k==20){if(e.getAction()==0)a.seriesRelated.enter(v);return true;}View next=index==-2?a.rows.findViewWithTag("season:"+season):cards.get(index);if(e.getAction()==0&&next!=null)next.requestFocus();return true;});}
 seasons.post(()->{View chosen=seasons.findViewWithTag("season:"+season);if(chosen!=null)seasons.scrollTo(Math.max(0,chosen.getLeft()-a.dp(12)),0);});if(!a.restoreFocus.isEmpty()){View v=a.rows.findViewWithTag(a.restoreFocus);if(v!=null){v.requestFocus();a.restoreFocus="";return;}}View active=a.rows.findViewWithTag("season:"+season);if(active!=null)active.requestFocus();}
 static void watchedMenu(MainActivity a,String id,Runnable refresh){new android.app.AlertDialog.Builder(a).setTitle("Watched status").setItems(new String[]{WatchLibrary.watched(a,id)?"Mark unwatched":"Mark watched"},(d,n)->{WatchLibrary.mark(a,id,!WatchLibrary.watched(a,id));refresh.run();}).setNegativeButton("Cancel",null).show();}
 static void sourceHeader(MainActivity a){if(a.selected==null)return;JSONObject title=a.selected;hero(a,title,82);if(a.rows.getChildCount()==0)return;View image=((ViewGroup)a.rows.getChildAt(0)).getChildAt(0);image.setOnLongClickListener(v->{watchedMenu(a,a.videoId,()->{});return true;});image.setFocusable(true);image.setContentDescription("Poster · hold OK for watched options");if(a.type.equals("movie")&&a.getSharedPreferences("history",0).getLong("position."+a.videoId,0)>0){Button reset=a.button("Saved position: "+PlaybackUi.time(a.getSharedPreferences("history",0).getLong("position."+a.videoId,0))+" · Reset to beginning",()->{a.getSharedPreferences("history",0).edit().putLong("position."+a.videoId,0).apply();android.widget.Toast.makeText(a,"Next playback starts from the beginning",0).show();});reset.setTextSize(11);a.rows.addView(reset,new LinearLayout.LayoutParams(-1,a.dp(28)));}}
 static void renderAgain(MainActivity a,JSONObject m,JSONObject full,String type){render(a,m,full,type);}
 static void movie(MainActivity a,JSONObject full,String id,String name,boolean restart){a.selected=full;a.type="movie";if(restart)a.getSharedPreferences("history",0).edit().putLong("position."+id,0).apply();a.videoId=id;a.videoName=name;a.sourceList();}
 static void watched(MainActivity a,String id,Runnable refresh){a.row(WatchLibrary.watched(a,id)?"✓ Watched · Mark unwatched":"Mark watched",()->{WatchLibrary.mark(a,id,!WatchLibrary.watched(a,id));refresh.run();});}
 static void episodes(MainActivity a,JSONObject m,JSONObject full,int season){a.screen(full.optString("name"),"");series(a,full,season);}
 static void episode(MainActivity a,JSONObject full,JSONObject episode,int season){a.episodeReturnDepth=a.back.size();a.selected=full;a.type="series";a.videoId=episode.optString("id");a.videoName=full.optString("name")+" · S"+season+" E"+episode.optInt("episode");a.sourceList();}
 static void gridKeys(List<View> cards,int columns){for(int i=0;i<cards.size();i++){final int at=i;cards.get(i).setOnKeyListener((v,k,e)->{int next=k==21?(at%columns==0?at:at-1):k==22?(at%columns==columns-1?at:Math.min(at+1,cards.size()-1)):k==19?(at<columns?at:at-columns):k==20?(at+columns<cards.size()?at+columns:at):-1;if(next<0)return false;if(e.getAction()==0)cards.get(next).requestFocus();return true;});}}
}
